/**
* Inspired by https://www.instagram.com/p/B-LNR3djZiO/
* Tried to capture a "VHS" aesthetic, ended up going for something more vaporwavy
* Genuary 18 - VHS
*/

let canvasWidth, canvasHeight
let tvWidth, tvHeight
let border
let MAIN_COLOR
let noiseSeeds
let fugueX
function setup () {
  canvasWidth = windowWidth
  canvasHeight = windowHeight
  border = 20
  tvWidth = canvasWidth - 2 * border
  tvHeight = canvasHeight - 2 * border
  let canvas = createCanvas(canvasWidth, canvasHeight)
  canvas.style('display', 'block')
  colorMode(HSB, 360, 100, 100, 100)

  MAIN_COLOR = color("#20C0A0"); // color('#CE1640')
  noiseSeeds = Array.from({ length: 10 }).map(() => int(random(10)))
	fugueX = canvasWidth / 2
}

function drawGridLines(horizon, fuguePoint, _color) {
  let gridY, gridX
  let gridWidth = tvWidth / 18
  let gridHeight = 10

  let ySpeed = 0.8
  let m = 1.2
  let yCycle = (frameCount * ySpeed) % gridHeight
  gridY = 0
  let i = 0
  let yh
  strokeWeight(1)
  stroke(_color)
  while (gridY < tvHeight - horizon) {
    yh = gridHeight * (m ** i)
    let yPartial = map(yCycle, 0, gridHeight, 0, yh)
    if (horizon + gridY + yPartial <= tvHeight) {
      line(0, horizon + gridY + yPartial, tvWidth, horizon + gridY + yPartial)
    }
    i += 1
    gridY = gridY + yh
  }

  gridX = 0
  while (gridX < tvWidth) {
    let gridXBot = fuguePoint[0] - ((fuguePoint[0] - gridX) * (tvHeight - fuguePoint[1]) / (horizon - fuguePoint[1]))
    let p1 = [gridX, horizon]
    let p2 = [gridXBot, tvHeight]
    // If the lines go off screen, cut them at the edge
    if (p2[0] < 0) {
      p2 = [0, horizon + (gridX * (horizon - fuguePoint[1]) / (fuguePoint[0] - gridX))]
    } else if (p2[0] > tvWidth) {
      p2 = [tvWidth, horizon + ((tvWidth - gridX) * (horizon - fuguePoint[1]) / (gridX - fuguePoint[0]))]
    }
    line(...p1, ...p2)
    gridX += gridWidth
  }
}

function drawMoon(moonRadius, _color) {
	push()
	rotate(-abs(sin(frameCount*0.02)*0.2))
  let numLines = 20 + sin(frameCount*0.02)*5
  for (let i = 0; i <= numLines; i++) {
    let y = cos(map(i, 0, numLines, PI, 2*PI)) * moonRadius
    let x1 = sqrt(moonRadius ** 2 - y ** 2)
    let h = map(abs(y), 0, moonRadius, 6, 1)
    noStroke()
    let gradient = drawingContext.createLinearGradient(-x1, y, x1, y)
    gradient.addColorStop(0, color(hue(window.color(_color)), saturation(window.color(_color)), 100, 100))
    gradient.addColorStop(1, color(hue(window.color(_color)), saturation(window.color(_color)), 100, 0))
    drawingContext.fillStyle = gradient
    fill(_color)
    quad(
      -x1, y-h/2,
      x1, y-h/6,
      x1, y+h/6,
      -x1, y+h/2
    )
  }
	pop()
}

let NOISE_FACTOR = 0.01
let moveSpeed = 0.005
function drawMountain(bgColor, horizon, height, color, seed, fuguePoint) {
  noiseSeed(seed)
  stroke(color)
  fill(bgColor)
  beginShape()
  vertex(-border, horizon)
  for (let i = -border; i <= tvWidth + border; i += 5) {
    var y = horizon - map(noise(i * NOISE_FACTOR + frameCount * moveSpeed - fuguePoint[0] * moveSpeed*2), 0, 1, height/3, height)
    vertex(i, y)
  }
  vertex(tvWidth + border, horizon)
  endShape(CLOSE)
}

function drawHorizonLines(horizon, _color) {
  let glowColor = color(hue(window.color(_color)), 30, 100)
  strokeWeight(5)
  stroke(_color)
  line(0, horizon, tvWidth, horizon)
  strokeWeight(1)
  stroke(glowColor)
  line(0, horizon, tvWidth, horizon)

  let minAlpha = 0
  let maxAlpha = 20
  let minWeight = 1
  let maxWeight = 3
  let sep = 10
  let n = 20
  for (let i = 0; i < n; i++) {
    let c = color(hue(window.color(_color)), saturation(window.color(_color)), brightness(window.color(_color)), map(i, 0, n, maxAlpha, minAlpha))
    stroke(c)
    strokeWeight(map(i, 0, n, maxWeight, minWeight))
    line(0, horizon - i * sep, tvWidth, horizon - i * sep)
  }
}

function drawScreen (mainColor, bgColor) {
  background(bgColor)

  let neonColor = color(hue(window.color(mainColor)), saturation(window.color(mainColor)), 100)
  drawingContext.shadowColor = neonColor
  drawingContext.shadowBlur = 40
  drawingContext.shadowOffsetX = 0
  drawingContext.shadowOffsetY = 0

  let horizon = tvHeight * 2 / 3
  let turnSpeed = 0.005
  let f = noise(frameCount * turnSpeed)

  let fuguePoint = [
    //tvWidth/4 + map(f, 0, 1, 0, tvWidth/2, true),
		map(fugueX, 0, canvasWidth, 0, tvWidth),
    tvHeight / 2
  ]

  drawGridLines(horizon, fuguePoint, mainColor)

  let moonCenter = [tvWidth * 13/16, tvHeight / 5]
  push()
  translate(...moonCenter)
  rotate(PI / 6)
  drawMoon(120, mainColor)
  pop()

  drawMountain(bgColor, horizon, tvHeight / 2, mainColor, noiseSeeds[0], fuguePoint)
  drawMountain(bgColor,horizon, tvHeight / 4, mainColor, noiseSeeds[1], fuguePoint)

  drawHorizonLines(horizon, mainColor)
}

function drawScreenShape(_color) {
  let A = 20, B = 40
  fill(_color)
  beginShape()
  vertex(0, 0)
  vertex(canvasWidth, 0)
  vertex(canvasWidth, canvasHeight)
  vertex(0, canvasHeight)
  beginContour()
  vertex(border + A, border + B)
  bezierVertex(border, border + tvHeight / 3, border, border + tvHeight / 3 * 2, border + A, border + tvHeight - B)
  bezierVertex(border + tvWidth / 3, border + tvHeight, border + tvWidth / 3 * 2, border + tvHeight, border + tvWidth - A, border + tvHeight - B)
  bezierVertex(border + tvWidth, border + tvHeight / 3 * 2, border + tvWidth, border + tvHeight / 3, border + tvWidth - A, border + B)
  bezierVertex(border + tvWidth / 3 * 2, border, border + tvWidth / 3, border, border + A, border + B)
  endContour()
  endShape(CLOSE)
}

function drawScreenNoise() {
  var sep = 50
  let minNoiseWidth = 100
  let maxNoiseWidth = 200
  let minOpacity = 0
  let maxOpacity = 10
  let N = 0.01
  for (let y = 0; y < tvHeight; y += sep) {
    let w = random(minNoiseWidth, maxNoiseWidth)
    let start = random(-w/2, w/2)
    while(start < tvWidth) {
      var c = color(0, 0, 100, random(minOpacity, maxOpacity))
      fill(c)
      stroke(c)
      strokeWeight(map(noise(start * N, y * N), 0, 1, 1, 3))
      // rect(start, y, w, sep)
      if (noise(start * N, y * N) > 0.5) {
        line(start, y + noise(y *frameCount * N) * sep, start + w, y + noise(y*frameCount * N) * sep)
      }
      start += w
      w = random(minNoiseWidth, maxNoiseWidth)
    }
  }
}

function draw () {
  let bgColor = '#0c142d'
  background(bgColor)

  // let currentColor = color((hue(window.color(MAIN_COLOR)) + frameCount/5) % 360, saturation(window.color(MAIN_COLOR)), brightness(window.color(MAIN_COLOR)), 100)
  let currentColor = color((hue(window.color(MAIN_COLOR)) + cos(frameCount*0.04) * 10 + 360) % 360, saturation(window.color(MAIN_COLOR)), brightness(window.color(MAIN_COLOR)), 100)

  push();
  translate(border, border)

  drawScreen(currentColor, bgColor)
  drawScreenNoise()
  pop()

  let screenColor = color(hue(window.color(currentColor)), saturation(window.color(currentColor)), brightness(window.color(currentColor)), 100)
  drawScreenShape(screenColor)
	if (fugueX >= canvasWidth / 6 && fugueX <= canvasWidth * 5 / 6) {
		let s = map(noise(frameCount * 0.01), 0, 1, -0.5, 0.5)
		fugueX = fugueX + (canvasWidth / 200) * s
	}
}


function windowResized() {
  resizeCanvas(windowWidth, windowHeight)
  canvasWidth = windowWidth
  canvasHeight = windowHeight
  tvWidth = canvasWidth - border * 2
  tvHeight = canvasHeight - border * 2
}

function mousePressed() {
  let fs = fullscreen()
  fullscreen(!fs)
}

function mouseMoved () {
	fugueX = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))
}
